const http=require('node:http'),fs=require('node:fs'),path=require('node:path');
const types={'.html':'text/html','.js':'text/javascript','.css':'text/css','.md':'text/plain'};
http.createServer((req,res)=>{let p;try{p=decodeURIComponent(new URL(req.url,'http://localhost').pathname);}catch{res.writeHead(400);res.end();return;}const file=path.resolve(__dirname,'.'+(p==='/'?'/index.html':p));if(!file.startsWith(__dirname+path.sep)){res.writeHead(403);res.end();return;}fs.readFile(file,(err,body)=>{if(err){res.writeHead(404);res.end('Not found');return;}res.writeHead(200,{'Content-Type':(types[path.extname(file)]||'application/octet-stream')+';charset=utf-8','Cache-Control':'no-store'});res.end(body);});}).listen(3011,'127.0.0.1',()=>console.log('Logan prototype: http://127.0.0.1:3011/'));
